fn is_palindrome(s: Str) -> Bool {
    let len = str_len(s)
    let mut i = 0
    let mut j = len - 1
    while i < j {
        if s[i] != s[j] {
            return false
        }
        i += 1
        j -= 1
    }
    true
}

